CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Equipment" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "EquipmentIdentifier" character varying(60) NOT NULL,
    "EquipmentIdentifierNormalized" character varying(60) NOT NULL,
    "Name" character varying(120) NOT NULL,
    "Description" character varying(300),
    "IsAvailable" boolean NOT NULL,
    CONSTRAINT "PK_Equipment" PRIMARY KEY ("Id")
);

CREATE TABLE "Students" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StudentNumber" character varying(40) NOT NULL,
    "StudentNumberNormalized" character varying(40) NOT NULL,
    "Name" character varying(120) NOT NULL,
    "ContactInformation" character varying(200),
    "IsAllowedToBorrow" boolean NOT NULL,
    CONSTRAINT "PK_Students" PRIMARY KEY ("Id")
);

CREATE TABLE "Borrowings" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "StudentId" integer NOT NULL,
    "EquipmentId" integer NOT NULL,
    "DateBorrowed" date NOT NULL,
    "ExpectedReturnDate" date NOT NULL,
    "ReturnedDate" date,
    "Status" integer NOT NULL,
    CONSTRAINT "PK_Borrowings" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Borrowings_Equipment_EquipmentId" FOREIGN KEY ("EquipmentId") REFERENCES "Equipment" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Borrowings_Students_StudentId" FOREIGN KEY ("StudentId") REFERENCES "Students" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX "IX_Borrowings_EquipmentId" ON "Borrowings" ("EquipmentId") WHERE "Status" = 0;

CREATE INDEX "IX_Borrowings_Status" ON "Borrowings" ("Status");

CREATE INDEX "IX_Borrowings_StudentId" ON "Borrowings" ("StudentId");

CREATE UNIQUE INDEX "IX_Equipment_EquipmentIdentifierNormalized" ON "Equipment" ("EquipmentIdentifierNormalized");

CREATE UNIQUE INDEX "IX_Students_StudentNumberNormalized" ON "Students" ("StudentNumberNormalized");

