COMMIT;

START TRANSACTION;
ALTER TABLE "Students" ADD CONSTRAINT "CK_Students_Contact_NotBlank" CHECK ("ContactInformation" IS NULL OR length(btrim("ContactInformation")) > 0);

ALTER TABLE "Students" ADD CONSTRAINT "CK_Students_Name_NotBlank" CHECK (length(btrim("Name")) > 0);

ALTER TABLE "Students" ADD CONSTRAINT "CK_Students_StudentNumber_Normalized" CHECK ("StudentNumberNormalized" = upper(btrim("StudentNumber")));

ALTER TABLE "Equipment" ADD CONSTRAINT "CK_Equipment_Description_NotBlank" CHECK ("Description" IS NULL OR length(btrim("Description")) > 0);

ALTER TABLE "Equipment" ADD CONSTRAINT "CK_Equipment_Identifier_Normalized" CHECK ("EquipmentIdentifierNormalized" = upper(btrim("EquipmentIdentifier")));

ALTER TABLE "Equipment" ADD CONSTRAINT "CK_Equipment_Name_NotBlank" CHECK (length(btrim("Name")) > 0);

ALTER TABLE "Borrowings" ADD CONSTRAINT "CK_Borrowings_Due_After_Checkout" CHECK ("ExpectedReturnDate" > "DateBorrowed");

ALTER TABLE "Borrowings" ADD CONSTRAINT "CK_Borrowings_Return_After_Checkout" CHECK ("ReturnedDate" IS NULL OR "ReturnedDate" >= "DateBorrowed");

ALTER TABLE "Borrowings" ADD CONSTRAINT "CK_Borrowings_Return_Status" CHECK (("Status" = 0 AND "ReturnedDate" IS NULL) OR ("Status" = 1 AND "ReturnedDate" IS NOT NULL));

